"""Same-sandbox tunnel-collision guard for multi-agent host installs (no I/O in the guard), and preflight's refusal of an
agent with no build context to install."""
import pytest
from agent_env.a2a_agent import A2AAgent
from agent_env.artifact.artifacts.docker_image import DockerImageArtifact
from agent_env.artifact.store import get_artifact_store
from agent_env.task_step.context import DeployedAgent, TaskStepContext
from agent_env.task_step.task_steps.install_agent import InstallAgentTaskStep


def _step(agent_name):
    return InstallAgentTaskStep(id="s", version=None, sandbox_name="vm", a2a_agent_id="agent-x", agent_name=agent_name)


def _ctx(agent_name="solver-a", api_url="https://t-8000.gw", sandbox_id="vm-1"):
    ctx = TaskStepContext()
    ctx.deployed_agents.append(DeployedAgent(agent_name=agent_name, api_url=api_url, sandbox_id=sandbox_id))
    return ctx


def test_tunnel_url_collision_rejected():
    with pytest.raises(RuntimeError, match="already serves"):
        _step("solver-b")._check_tunnel_collision(_ctx(), "vm-1", "https://t-8000.gw", 8000)


def test_distinct_port_passes():
    _step("solver-b")._check_tunnel_collision(_ctx(), "vm-1", "https://t-8010.gw", 8010)


def test_other_sandbox_ignored():
    _step("solver-b")._check_tunnel_collision(_ctx(sandbox_id="vm-2"), "vm-1", "https://t-8000.gw", 8000)


# What preflight refuses at save: install/v1 copies an agent's source files from its image's build context

def _agent_with(**image_fields):
    image = get_artifact_store().put_document(DockerImageArtifact(id="agent-x-image", description="d", **image_fields))
    return A2AAgent.put(id="agent-x", docker_image_artifact=image)


def test_preflight_refuses_an_agent_whose_image_has_no_build_context(local_stores):
    _agent_with(image_name="ghcr.io/team/agent@sha256:" + "0" * 64)

    assert _step("solver").preflight() == [
        "install_agent 's': Agent agent-x v1 has no build_context_object_url on its docker_image_artifact; install/v1 "
        "needs the build context (agent source files) to install into the task container"]


def test_preflight_passes_an_agent_with_a_build_context(local_stores):
    _agent_with(image_name="local/agent-x-0123456789ab:v1", build_context_object_url="s3://bucket/ctx.tar.gz")

    assert _step("solver").preflight() == []


def test_preflight_leaves_an_agent_the_store_doesnt_hold_to_the_run(local_stores):
    """The run's a2a_agent_id override can name another agent, so a task saved naming a placeholder still saves."""
    assert _step("solver").preflight() == []

from __future__ import annotations

import threading

import httpx
import pytest

import agent_env.artifact.artifacts.file_artifact_universe as universe_mod
from agent_env.config import configure
from agent_env.task_step.context import TaskStepContext
from agent_env.task_step.snapshot_utils import agent_state_capture as capture
from agent_env.task_step.task_steps.deploy_agent import DeployAgentTaskStep
from tst.util.granting_object_store import GrantingObjectStore

BUNDLE_KEY = "agent_snapshots/snapshot-1/3-deadbeef"


class _Universe:
    id = "snapshot-1"
    version = 3

    def __init__(self, store: GrantingObjectStore, files: tuple[str, ...]) -> None:
        for name in files:
            store.put(f"{BUNDLE_KEY}/{name}", b"snapshot bytes")
        self.bundle_object_url = store.object_url(BUNDLE_KEY) + "/"
        self.file_artifact_refs = None
        self.file_artifact_ids = {
            name: f"artifact-{index}" for index, name in enumerate(files)
        }


def _step() -> DeployAgentTaskStep:
    return DeployAgentTaskStep(
        id="deploy",
        version=None,
        agent_name="solver",
        agent_snapshot_files_artifact_id="snapshot-1",
        agent_snapshot_files_artifact_version=3,
        agent_snapshot_target_context_id="restored-context",
    )


def _card(*, objects: bool = True, legacy: bool = True) -> dict:
    variants = []
    if legacy:
        variants.append({"required": ["s3_prefix"]})
    if objects:
        variants.append({"required": ["objects"]})
    return {
        "capabilities": {
            "extensions": [
                {
                    "uri": "urn:agentenv:snapshot/v1",
                    "params": {
                        "methods": {
                            "load": {
                                "endpoint": "/custom/snapshot",
                                "request": {"oneOf": variants},
                            },
                        },
                    },
                }
            ]
        }
    }


@pytest.fixture
def store(tmp_path) -> GrantingObjectStore:
    store = GrantingObjectStore(str(tmp_path))
    configure(object_store=store)
    return store


def _install(
    monkeypatch, universe: _Universe, response: dict, *, status_code: int = 200
) -> list[dict]:
    monkeypatch.setattr(
        universe_mod.FileArtifactUniverse,
        "get",
        classmethod(lambda cls, artifact_id, version: universe),
    )
    requests: list[dict] = []

    async def fake_request(
        self, method, url, *, json=None, timeout=None, **kwargs
    ):  # noqa: A002
        requests.append(
            {"method": method, "url": url, "json": json, "timeout": timeout}
        )
        return httpx.Response(
            status_code, json=response, request=httpx.Request(method, url)
        )

    monkeypatch.setattr(httpx.AsyncClient, "request", fake_request)
    return requests


PORTABLE = (capture.SNAPSHOT_TRAJECTORY_OBJECT_NAME, capture.SNAPSHOT_WORKSPACE_OBJECT_NAME)
LEGACY = ("conversation.jsonl", "workspace.tar.gz")


@pytest.mark.asyncio
async def test_load_prefers_objects_for_a_portable_snapshot(monkeypatch, store):
    requests = _install(
        monkeypatch, _Universe(store, PORTABLE), {"context_id": "restored-context"}
    )
    context = TaskStepContext()

    await _step()._load_snapshot("https://agent", _card(), "agent-1", context, sandbox_type="local")

    sent = requests[0]
    assert sent["url"] == "https://agent/custom/snapshot"
    assert set(sent["json"]) == {"objects", "target_context_id"}
    assert set(sent["json"]["objects"]) == {"trajectory", "workspace"}
    assert all(
        descriptor["media_type"] == "application/octet-stream"
        and descriptor["size_bytes"] == len(b"snapshot bytes")
        for descriptor in sent["json"]["objects"].values()
    )
    assert {url.rsplit("/", 1)[-1] for url in store.granted} == set(PORTABLE)
    assert context.metadata["agent_loaded_snapshots"][0]["context_id"] == (
        "restored-context"
    )


@pytest.mark.asyncio
async def test_load_reads_object_metadata_off_the_event_loop(monkeypatch, store):
    _install(monkeypatch, _Universe(store, PORTABLE), {"context_id": "restored-context"})
    loop_threads = []
    metadata = store.get_object_metadata_at

    def recording(url):
        loop_threads.append(threading.current_thread() is threading.main_thread())
        return metadata(url)

    monkeypatch.setattr(store, "get_object_metadata_at", recording)

    await _step()._load_snapshot("https://agent", _card(), "agent-1", TaskStepContext(), sandbox_type="local")

    assert loop_threads == [False, False]


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "card, files",
    [
        (_card(), LEGACY),
        (_card(objects=False), LEGACY),
        (_card(legacy=False), ("workspace.tar.gz",)),
    ],
    ids=["dual-agent", "legacy-only-agent", "objects-only-agent"],
)
async def test_a_legacy_snapshot_cannot_be_restored(monkeypatch, store, card, files):
    requests = _install(monkeypatch, _Universe(store, files), {"context_id": "wrong"})

    with pytest.raises(RuntimeError, match="is not a portable snapshot, so it cannot be restored"):
        await _step()._load_snapshot("https://agent", card, "agent-1", TaskStepContext(), sandbox_type="local")

    assert not store.granted
    assert not requests


@pytest.mark.asyncio
async def test_load_validates_the_object_response(monkeypatch, store):
    _install(monkeypatch, _Universe(store, PORTABLE[:1]), {"ok": True})

    with pytest.raises(RuntimeError, match="invalid object response"):
        await _step()._load_snapshot(
            "https://agent", _card(), "agent-1", TaskStepContext(), sandbox_type="local"
        )


@pytest.mark.asyncio
async def test_load_ignores_response_fields_it_does_not_know(monkeypatch, store):
    _install(
        monkeypatch,
        _Universe(store, PORTABLE[:1]),
        {"ok": True, "context_id": "restored-context"},
    )
    context = TaskStepContext()

    await _step()._load_snapshot("https://agent", _card(), "agent-1", context, sandbox_type="local")

    assert context.metadata["agent_loaded_snapshots"][0]["context_id"] == (
        "restored-context"
    )


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "card, grants, refusal",
    [
        (_card(objects=False), True, "does not advertise the object form"),
        (_card(), False, "does not issue transfer grants"),
    ],
    ids=["legacy-only-agent", "store-without-grants"],
)
async def test_a_portable_snapshot_loads_through_objects_or_not_at_all(
    monkeypatch, store, card, grants, refusal
):
    store.supports_transfer_grants = grants
    requests = _install(monkeypatch, _Universe(store, PORTABLE[:1]), {"context_id": "wrong"})

    with pytest.raises(RuntimeError, match=refusal):
        await _step()._load_snapshot("https://agent", card, "agent-1", TaskStepContext(), sandbox_type="local")

    assert not store.granted
    assert not requests

from __future__ import annotations

import threading
from datetime import UTC, datetime, timedelta

import httpx
import pytest

from agent_env.config import configure
from agent_env.store import GrantUnavailableError
from agent_env.task_step.context import TaskStepContext
from agent_env.a2a_agent import object_transfer
from agent_env.a2a_agent.object_transfer import ObjectLimits, changelog_apply_call
from agent_env.task_step.task_steps.deploy_agent import DeployAgentTaskStep
from tst.util.granting_object_store import GrantingObjectStore

NAMESPACE_KEY = "agent_changelog/run-1/solver"


@pytest.fixture
def store(tmp_path) -> GrantingObjectStore:
    store = GrantingObjectStore(str(tmp_path))
    configure(object_store=store)
    return store


def _increments(store: GrantingObjectStore, *names: str, data: bytes = b"increment") -> str:
    for name in names:
        store.put(f"{NAMESPACE_KEY}/{name}", data)
    return store.object_url(NAMESPACE_KEY)


def _card(
    *,
    enable_objects: bool = True,
    enable_legacy: bool = True,
    apply_objects: bool = True,
) -> dict:
    enable_variants = []
    if enable_legacy:
        enable_variants.append({"required": ["s3_prefix"]})
    if enable_objects:
        enable_variants.append({"required": ["write_namespace"]})
    apply_variants = [{"required": ["s3_prefix"]}]
    if apply_objects:
        apply_variants.append({"required": ["increments"]})
    return {
        "capabilities": {
            "extensions": [
                {
                    "uri": "urn:agentenv:snapshot/v1",
                    "params": {
                        "methods": {
                            "enable-changelog": {
                                "endpoint": "/custom/changelog",
                                "request": {"oneOf": enable_variants},
                            },
                            "apply-changelog": {
                                "endpoint": "/custom/changelog",
                                "request": {"oneOf": apply_variants},
                            },
                        }
                    },
                }
            ]
        }
    }


def _step(**kwargs) -> DeployAgentTaskStep:
    return DeployAgentTaskStep(
        id="deploy",
        version=None,
        agent_name="solver",
        **kwargs,
    )


def _install(monkeypatch, response: dict, *, status_code: int = 200) -> list[dict]:
    requests: list[dict] = []

    async def fake_request(
        self, method, url, *, json=None, timeout=None, **kwargs
    ):  # noqa: A002
        requests.append(
            {"method": method, "url": url, "json": json, "timeout": timeout}
        )
        return httpx.Response(
            status_code, json=response, request=httpx.Request(method, url)
        )

    monkeypatch.setattr(httpx.AsyncClient, "request", fake_request)
    return requests


def _run_context() -> TaskStepContext:
    context = TaskStepContext()
    context.instance_id = "run-1"
    return context


def _granted_names(store: GrantingObjectStore) -> list[str]:
    return [url.rsplit("/", 1)[-1] for url in store.granted]


def test_changelog_grant_lifetime_tracks_resolved_agent_ttl():
    assert _step(ttl_seconds=7_200)._resolved_ttl_seconds(TaskStepContext()) == 7_200
    context = TaskStepContext(metadata={"user_overrides": {"ttl_seconds": 28_800}})
    assert _step(ttl_seconds=7_200)._resolved_ttl_seconds(context) == 28_800
    assert _step()._resolved_ttl_seconds(TaskStepContext()) == 7_200


@pytest.mark.asyncio
async def test_enable_prefers_a_bounded_namespace_grant(monkeypatch, store):
    requests = _install(monkeypatch, {"roots": ["workspace"]})
    context = _run_context()

    await _step(enable_agent_changelog=True)._configure_agent_changelog(
        "https://agent", _card(), context, expires_in=28_800, sandbox_type="local"
    )

    sent = requests[0]
    assert sent["url"] == "https://agent/custom/changelog"
    assert set(sent["json"]) == {"write_namespace"}
    grant = sent["json"]["write_namespace"]
    assert grant["root_path"] == NAMESPACE_KEY
    assert grant["max_objects"] == object_transfer.CHANGELOG_LIMITS.max_objects
    expires_at = datetime.fromisoformat(grant["expires_at"])
    assert abs(expires_at - (datetime.now(UTC) + timedelta(seconds=28_800))) < timedelta(
        seconds=5
    )
    assert context.metadata["agent_changelog"] == [
        {
            "agent_name": "solver",
            "roots": ["workspace"],
            "transfer_mode": "objects",
            "object_url": store.object_url(NAMESPACE_KEY),
        }
    ]


@pytest.mark.asyncio
async def test_the_changelog_namespace_is_under_the_fixture_prefix(monkeypatch, store):
    monkeypatch.setenv("AGENT_ENV_FIXTURE_PREFIX", "fx")
    configure(object_store=store)
    requests = _install(monkeypatch, {"roots": ["workspace"]})
    context = _run_context()

    await _step(enable_agent_changelog=True)._configure_agent_changelog(
        "https://agent", _card(), context, expires_in=600, sandbox_type="local"
    )

    assert requests[0]["json"]["write_namespace"]["root_path"] == f"fx/{NAMESPACE_KEY}"
    assert context.metadata["agent_changelog"][0]["object_url"] == store.object_url(f"fx/{NAMESPACE_KEY}")


@pytest.mark.asyncio
@pytest.mark.parametrize("enable_legacy", [True, False], ids=["dual", "portable-only"])
async def test_enable_fails_when_the_store_cannot_grant_the_lifetime(
    monkeypatch, store, enable_legacy
):
    def unavailable(*args, **kwargs):
        raise GrantUnavailableError("credentials expire first")

    monkeypatch.setattr(store, "issue_upload_policy", unavailable)
    requests = _install(monkeypatch, {"roots": ["workspace"]})

    with pytest.raises(
        GrantUnavailableError,
        match="'solver': the object store cannot issue its namespace grant: credentials expire first",
    ):
        await _step(enable_agent_changelog=True)._configure_agent_changelog(
            "https://agent",
            _card(enable_legacy=enable_legacy),
            _run_context(),
            expires_in=28_800,
         sandbox_type="local",
        )

    assert not requests


@pytest.mark.asyncio
@pytest.mark.parametrize("enable_legacy", [True, False], ids=["dual", "portable-only"])
async def test_enable_on_a_store_without_grants_is_refused(monkeypatch, store, enable_legacy):
    store.supports_transfer_grants = False
    requests = _install(monkeypatch, {"roots": ["workspace"]})

    with pytest.raises(RuntimeError, match="does not issue transfer grants"):
        await _step(enable_agent_changelog=True)._configure_agent_changelog(
            "https://agent", _card(enable_legacy=enable_legacy), _run_context(), expires_in=7_200, sandbox_type="local"
        )

    assert not requests
    assert store.granted == []


@pytest.mark.asyncio
async def test_enable_is_refused_for_an_agent_without_the_object_form(monkeypatch, store):
    requests = _install(monkeypatch, {"roots": ["workspace"]})

    with pytest.raises(RuntimeError, match="does not advertise the object form"):
        await _step(enable_agent_changelog=True)._configure_agent_changelog(
            "https://agent", _card(enable_objects=False), _run_context(), expires_in=7_200, sandbox_type="local"
        )

    assert not requests


@pytest.mark.asyncio
async def test_apply_lists_validates_and_sends_ordered_read_grants(monkeypatch, store):
    namespace = _increments(store, "000002.tar", "000000.tar", "000001.tar")
    requests = _install(monkeypatch, {"count": 2, "context_id": "continued"})
    listed_on: list[int] = []
    list_at = store.list_at
    monkeypatch.setattr(
        store, "list_at", lambda url: (listed_on.append(threading.get_ident()), list_at(url))[1]
    )
    step = _step(
        agent_changelog_object_url=namespace,
        agent_changelog_toolcall_position_exclusive=2,
        agent_snapshot_target_context_id="continued",
    )
    context = TaskStepContext()

    event_loop_thread = threading.get_ident()
    await step._apply_agent_changelog("https://agent", _card(), context, sandbox_type="local")

    sent = requests[0]["json"]
    assert [item["sequence"] for item in sent["increments"]] == [0, 1]
    assert {item["object"]["media_type"] for item in sent["increments"]} == {
        "application/octet-stream"
    }
    assert sent["resume_conversation"] is True
    assert sent["target_context_id"] == "continued"
    assert _granted_names(store) == ["000000.tar", "000001.tar"]
    assert context.metadata["agent_changelog_rewinds"][0]["transfer_mode"] == "objects"
    assert listed_on and listed_on[0] != event_loop_thread


@pytest.mark.asyncio
async def test_apply_uses_absolute_tool_call_positions_for_the_cutoff(monkeypatch, store):
    namespace = _increments(store, "000007.tar", "000002.tar", "000004.tar")
    requests = _install(monkeypatch, {"count": 2})
    step = _step(
        agent_changelog_object_url=namespace,
        agent_changelog_toolcall_position_exclusive=7,
    )

    await step._apply_agent_changelog("https://agent", _card(), TaskStepContext(), sandbox_type="local")

    assert [item["sequence"] for item in requests[0]["json"]["increments"]] == [2, 4]
    assert _granted_names(store) == ["000002.tar", "000004.tar"]


@pytest.mark.asyncio
async def test_apply_allows_a_cutoff_beyond_the_last_tool_call(monkeypatch, store):
    namespace = _increments(store, "000002.tar", "000004.tar")
    requests = _install(monkeypatch, {"count": 2})
    step = _step(
        agent_changelog_object_url=namespace,
        agent_changelog_toolcall_position_exclusive=99,
    )

    await step._apply_agent_changelog("https://agent", _card(), TaskStepContext(), sandbox_type="local")

    assert [item["sequence"] for item in requests[0]["json"]["increments"]] == [2, 4]


@pytest.mark.asyncio
async def test_apply_rejects_duplicate_tool_call_positions(monkeypatch, store):
    namespace = _increments(store, "000002.tar", "000002.json")
    requests = _install(monkeypatch, {"count": 2})

    with pytest.raises(ValueError, match="strictly increasing"):
        await _step(agent_changelog_object_url=namespace)._apply_agent_changelog(
            "https://agent", _card(), TaskStepContext(), sandbox_type="local"
        )
    assert not requests


@pytest.mark.asyncio
async def test_apply_rejects_unsequenced_objects_in_a_portable_namespace(monkeypatch, store):
    namespace = _increments(store, "manifest.json", "workspace.tar.gz")
    requests = _install(monkeypatch, {"count": 2})

    with pytest.raises(ValueError, match="zero-padded sequence names"):
        await _step(agent_changelog_object_url=namespace)._apply_agent_changelog(
            "https://agent", _card(), TaskStepContext(), sandbox_type="local"
        )
    assert not requests
    assert store.granted == []


@pytest.mark.asyncio
@pytest.mark.parametrize(
    "names, cutoff",
    [((), None), (("000000.tar", "000001.tar"), 0)],
    ids=["empty-namespace", "cutoff-before-the-first-tool-call"],
)
async def test_apply_sends_the_empty_baseline_when_no_increment_is_selected(
    monkeypatch, store, names, cutoff
):
    namespace = _increments(store, *names)
    requests = _install(monkeypatch, {"count": 0, "context_id": "baseline"})
    context = TaskStepContext()
    step = _step(
        agent_changelog_object_url=namespace,
        agent_changelog_toolcall_position_exclusive=cutoff,
    )

    await step._apply_agent_changelog("https://agent", _card(), context, sandbox_type="local")

    assert requests[0]["json"]["increments"] == []
    assert store.granted == []
    assert context.metadata["agent_changelog_rewinds"][0]["context_id"] == "baseline"


_APPLY_OBJECTS = {"request": {"required": ["increments"]}}


def _apply_call(store, source_url):
    return changelog_apply_call(
        _APPLY_OBJECTS, store, agent_name="solver", source_url=source_url, sandbox_type="local"
    )


def _limit_changelog(monkeypatch, **limits):
    monkeypatch.setattr(
        object_transfer,
        "CHANGELOG_LIMITS",
        ObjectLimits(**{**vars(object_transfer.CHANGELOG_LIMITS), **limits}),
    )


def test_apply_rejects_too_many_increments_before_issuing_grants(monkeypatch, store):
    namespace = _increments(store, "000000.tar", "000001.tar")
    _limit_changelog(monkeypatch, max_objects=1)

    with pytest.raises(ValueError, match="the limit is 1"):
        _apply_call(store, namespace)

    assert store.granted == []


def test_apply_rejects_a_namespace_over_the_aggregate_limit(monkeypatch, store):
    namespace = _increments(store, "000000.tar", "000001.tar", data=b"sixsix")
    _limit_changelog(monkeypatch, max_total_bytes=10)

    with pytest.raises(ValueError, match="10-byte limit"):
        _apply_call(store, namespace)


def test_apply_counts_empty_increments_as_capture_does(monkeypatch, store):
    store.put(f"{NAMESPACE_KEY}/000000.tar", b"")
    store.put(f"{NAMESPACE_KEY}/000001.tar", b"ten bytes!")
    _limit_changelog(monkeypatch, max_total_bytes=10)

    call = _apply_call(store, store.object_url(NAMESPACE_KEY))

    assert [item["object"]["size_bytes"] for item in call.payload["increments"]] == [0, 10]


@pytest.mark.asyncio
async def test_a_source_is_not_sent_to_an_agent_without_the_object_apply_form(monkeypatch, store):
    namespace = _increments(store, "000000.tar")
    requests = _install(monkeypatch, {"ok": True, "count": 1})

    with pytest.raises(RuntimeError, match="does not advertise the object form"):
        await _step(agent_changelog_object_url=namespace)._apply_agent_changelog(
            "https://agent", _card(apply_objects=False), TaskStepContext(), sandbox_type="local"
        )

    assert not requests
    assert store.granted == []


def test_a_changelog_source_round_trips():
    step = _step(
        agent_changelog_object_url="s3://artifact-bucket/agent_changelog/run-1/solver",
        agent_changelog_toolcall_position_exclusive=2,
    )

    restored = DeployAgentTaskStep.from_dict(step.to_dict())

    assert restored.agent_changelog_object_url == step.agent_changelog_object_url
    assert restored.agent_changelog_toolcall_position_exclusive == 2


def test_a_cutoff_needs_a_changelog_source():
    with pytest.raises(ValueError, match="requires agent_changelog_object_url"):
        _step(agent_changelog_toolcall_position_exclusive=2)

